import React, { useCallback, useMemo, useState } from 'react';
import { useIntl } from 'react-intl';

import { ColumnSettingsList } from './ColumnSettingsList.js';
import { ModalFooter } from './ModalFooter.js';
import { SearchInput } from './SearchInput.js';
import {
  createVisibilityCheckbox,
  generateColumnCheckboxes,
} from './VisibilitySettings/visibility-checkbox-utils.js';
import { VisibilityCheckbox } from './VisibilitySettings/VisibilityCheckbox.js';
import { useBreakpoint } from '../../../core/hooks/useBreakpoint.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { Modal } from '../../../overlays/modal/Modal.js';
import { ColumnMinInstance } from '../../types/internal-table-types.js';
import { ColumnVisibilityConfig } from '../../types/table-config-types.js';
import {
  createCheckboxOnChange,
  getStateOfAll,
  getUpdatedVisibility,
} from '../../utils/visibility-utils.js';
// #region Typings
interface ColumnSettingsModalProps {
  visibilitySettings: boolean;
  columnOrderSettings: boolean;
  onVisibilityChange?: (visibility: ColumnVisibilityConfig) => void;
  visibility: ColumnVisibilityConfig;
  allColumns: ColumnMinInstance[];
  onColumnOrderChange: (columnOrder: string[]) => void;
}
// #endregion Typings

export const ColumnSettingsModal = (props: ColumnSettingsModalProps) => {
  const {
    onVisibilityChange,
    visibility,
    allColumns,
    columnOrderSettings,
    visibilitySettings,
    onColumnOrderChange,
  } = props;

  const mobileView = useBreakpoint('(max-width: 480px)');
  const intl = useIntl();
  const [localVisibility, setLocalVisibility] = useState(visibility);
  const [configuredColumns, setConfiguredColumns] = useState(allColumns);
  const [activeFilterValue, setActiveFilterValue] = useState<string>('');
  const [showModal, setShowModal] = useState(true);

  const caseInsensitiveFilterValue = activeFilterValue.toLocaleLowerCase();
  const columnVisibilityEntries = Object.entries(localVisibility);
  const configuredColumnOrder = configuredColumns?.map((column) => column.id);

  const onSearchInputChange = (value: string) => {
    setActiveFilterValue(value);
  };

  const showAll = getStateOfAll(columnVisibilityEntries);

  // if modal is dismissed or canceled reset to the previous states locally
  const resetColumnSettings = useCallback(() => {
    setConfiguredColumns(allColumns ?? []);
    setLocalVisibility(visibility);
    setActiveFilterValue('');
  }, [allColumns, visibility]);

  const onShowAllChange = (checked: boolean) => {
    const updatedVisibility = getUpdatedVisibility(
      localVisibility,
      checked ? 'visible' : 'hidden',
      (configuredColumns as ColumnMinInstance[]) ?? [],
    );

    if (onVisibilityChange) {
      setLocalVisibility(updatedVisibility);
    }
  };

  const checkboxOnVisibilityChange = (visibility: ColumnVisibilityConfig) => {
    if (onVisibilityChange) {
      setLocalVisibility(visibility);
    }
  };

  const checkboxOnChange = createCheckboxOnChange(
    (configuredColumns as ColumnMinInstance[]) ?? [],
    localVisibility,
    checkboxOnVisibilityChange,
  );

  const { columnCheckboxes } = useMemo(() => {
    return visibilitySettings
      ? generateColumnCheckboxes(
          localVisibility,
          (allColumns as ColumnMinInstance[]) ?? [],
          checkboxOnChange,
          createVisibilityCheckbox,
        )
      : { columnCheckboxes: null, hiddenColumnCount: 0 };
  }, [allColumns, checkboxOnChange, localVisibility, visibilitySettings]);

  const visibilityIsConfigured = columnCheckboxes?.length !== 0;

  const handleConfirm = () => {
    onVisibilityChange && onVisibilityChange(localVisibility);
    onColumnOrderChange(configuredColumnOrder);
    setShowModal(false);
  };

  const handleCancel = () => {
    resetColumnSettings();
    setShowModal(false);
  };

  return (
    <Modal
      show={showModal}
      title={intl.formatMessage({
        defaultMessage: 'Columns',
        id: 'tznlZbNaiUJ1dPqb',
        description: 'Column settings modal title',
      })}
      size={'small'}
      onDismiss={handleCancel}
      footer={<ModalFooter onConfirm={handleConfirm} onCancel={handleCancel} />}
    >
      {visibilitySettings && (
        <Flex
          flexDirection={mobileView ? 'column' : 'row'}
          alignItems={mobileView ? 'flex-start' : 'center'}
          paddingBottom={20}
        >
          {!activeFilterValue && visibilityIsConfigured && (
            <VisibilityCheckbox
              name={intl.formatMessage({
                defaultMessage: 'Show/hide all',
                id: 'xYagPfCP0AY72G3+',
                description: 'Show or hide all checkbox label',
              })}
              accessorOrId={'_showAll_'}
              checked={showAll}
              checkboxOnChange={(accessor, checked) =>
                onShowAllChange && onShowAllChange(checked)
              }
              order={mobileView ? 2 : 0}
            />
          )}
          {visibilitySettings && visibilityIsConfigured && (
            <SearchInput
              value={activeFilterValue}
              onChange={onSearchInputChange}
              mobileView={mobileView}
              placeholder={intl.formatMessage({
                defaultMessage: 'Search',
                id: 'TIVnKWerQ6BuCdAB',
                description: 'Search placeholder',
              })}
            />
          )}
        </Flex>
      )}
      <Flex gap={0} flexDirection="column">
        <Flex flexDirection="column">
          {allColumns && (
            <ColumnSettingsList
              configuredColumns={configuredColumns}
              columnCheckboxes={columnCheckboxes ?? []}
              activeFilterValue={caseInsensitiveFilterValue}
              onColumnsReordering={setConfiguredColumns}
              columnOrderSettings={columnOrderSettings}
            />
          )}
        </Flex>
      </Flex>
    </Modal>
  );
};
